ready := make(chan struct{})   // unbuffered: carries no value, only the signal

func waiter() {
    <-ready                    // suspends until the condition is signalled
    useResource()
}

func notifier() {
    prepareResource()          // change the state first
    close(ready)               // broadcast: every waiter may proceed
}

