var mu sync.Mutex
var cond = sync.NewCond(&mu)
var q []int

func take() int {
    mu.Lock()
    for len(q) == 0 { cond.Wait() }   // unlocks mu, suspends, re-locks on return
    v := q[0]; q = q[1:]
    mu.Unlock()
    return v
}
func put(v int) { mu.Lock(); q = append(q, v); cond.Signal(); mu.Unlock() }
